import base64
import hashlib
import os
import secrets
import time
import urllib.parse
from dataclasses import dataclass
from typing import Any, Dict, Optional
from urllib.parse import urlencode

import requests


@dataclass
class PKCELoginState:
    state: str
    nonce: str
    code_verifier: str
    code_challenge: str
    created_at: int


class Auth0PKCELoginFlow:
    def __init__(
        self,
        domain: Optional[str] = None,
        client_id: Optional[str] = None,
        redirect_uri: Optional[str] = None,
        scope: str = "openid profile email",
        audience: Optional[str] = None,
        session_store: Optional[Dict[str, PKCELoginState]] = None,
        timeout: int = 15,
    ) -> None:
        self.domain = (domain or os.environ["AUTH0_DOMAIN"]).strip()
        self.client_id = (client_id or os.environ["AUTH0_CLIENT_ID"]).strip()
        self.redirect_uri = redirect_uri or os.environ["AUTH0_REDIRECT_URI"]
        self.scope = scope
        self.audience = audience or os.environ.get("AUTH0_AUDIENCE")
        self.timeout = timeout
        self.session_store: Dict[str, PKCELoginState] = session_store if session_store is not None else {}

        self.authorization_endpoint = f"https://{self.domain}/authorize"
        self.token_endpoint = f"https://{self.domain}/oauth/token"
        self.userinfo_endpoint = f"https://{self.domain}/userinfo"

    @staticmethod
    def _base64url(data: bytes) -> str:
        return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")

    @staticmethod
    def _generate_code_verifier(length: int = 64) -> str:
        verifier = secrets.token_urlsafe(length)
        return verifier[:128]

    @classmethod
    def _generate_code_challenge(cls, code_verifier: str) -> str:
        digest = hashlib.sha256(code_verifier.encode("ascii")).digest()
        return cls._base64url(digest)

    @staticmethod
    def _generate_state() -> str:
        return secrets.token_urlsafe(32)

    @staticmethod
    def _generate_nonce() -> str:
        return secrets.token_urlsafe(32)

    def create_authorization_url(
        self,
        extra_params: Optional[Dict[str, str]] = None,
        prompt: Optional[str] = None,
        connection: Optional[str] = None,
        organization: Optional[str] = None,
    ) -> Dict[str, Any]:
        state = self._generate_state()
        nonce = self._generate_nonce()
        code_verifier = self._generate_code_verifier()
        code_challenge = self._generate_code_challenge(code_verifier)

        self.session_store[state] = PKCELoginState(
            state=state,
            nonce=nonce,
            code_verifier=code_verifier,
            code_challenge=code_challenge,
            created_at=int(time.time()),
        )

        params = {
            "response_type": "code",
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "scope": self.scope,
            "state": state,
            "nonce": nonce,
            "code_challenge": code_challenge,
            "code_challenge_method": "S256",
        }

        if self.audience:
            params["audience"] = self.audience
        if prompt:
            params["prompt"] = prompt
        if connection:
            params["connection"] = connection
        if organization:
            params["organization"] = organization
        if extra_params:
            params.update(extra_params)

        return {
            "authorization_url": f"{self.authorization_endpoint}?{urlencode(params)}",
            "state": state,
            "nonce": nonce,
            "code_verifier": code_verifier,
            "code_challenge": code_challenge,
        }

    def exchange_code_for_tokens(
        self,
        callback_query: str,
        max_state_age_seconds: int = 600,
    ) -> Dict[str, Any]:
        query_params = urllib.parse.parse_qs(callback_query, keep_blank_values=True)
        if "error" in query_params:
            raise ValueError(
                f"Authorization failed: {query_params.get('error', ['unknown'])[0]} - "
                f"{query_params.get('error_description', [''])[0]}"
            )

        code = query_params.get("code", [None])[0]
        state = query_params.get("state", [None])[0]

        if not code or not state:
            raise ValueError("Missing required callback parameters: code and/or state")

        pkce_state = self.session_store.get(state)
        if not pkce_state:
            raise ValueError("Invalid or expired state")

        if int(time.time()) - pkce_state.created_at > max_state_age_seconds:
            self.session_store.pop(state, None)
            raise ValueError("State has expired")

        payload = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "code": code,
            "redirect_uri": self.redirect_uri,
            "code_verifier": pkce_state.code_verifier,
        }

        response = requests.post(
            self.token_endpoint,
            json=payload,
            headers={"Content-Type": "application/json"},
            timeout=self.timeout,
        )
        response.raise_for_status()
        token_response = response.json()

        self.session_store.pop(state, None)

        return token_response

    def fetch_userinfo(self, access_token: str) -> Dict[str, Any]:
        response = requests.get(
            self.userinfo_endpoint,
            headers={"Authorization": f"Bearer {access_token}"},
            timeout=self.timeout,
        )
        response.raise_for_status()
        return response.json()

    def handle_callback_and_fetch_profile(
        self,
        callback_query: str,
        max_state_age_seconds: int = 600,
    ) -> Dict[str, Any]:
        tokens = self.exchange_code_for_tokens(
            callback_query=callback_query,
            max_state_age_seconds=max_state_age_seconds,
        )

        access_token = tokens.get("access_token")
        profile = self.fetch_userinfo(access_token) if access_token else None

        return {
            "tokens": tokens,
            "userinfo": profile,
        }
